'use server'

import { createClient } from '@/utils/supabase/server'
import { revalidatePath } from 'next/cache'

// Update the type interface
type SubmitPayload = {
  cadetId: string
  offenseTypeId: string
  dateOfOffense: string
  notes: string       // Green Sheet Summary
  explanation: string // Full Narrative
}

export async function submitReport(payload: SubmitPayload) {
  const supabase = createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return { error: 'Unauthorized' }

  // Insert with the new column
  const { error } = await supabase.from('demerit_reports').insert({
    subject_cadet_id: payload.cadetId,
    submitted_by: user.id,
    offense_type_id: payload.offenseTypeId,
    date_of_offense: payload.dateOfOffense,
    notes: payload.notes,                    // Short Summary
    report_explanation: payload.explanation, // Full Narrative
    status: 'pending_approval'
  })

  if (error) return { error: error.message }

  revalidatePath('/')
  return { success: true }
}