'use client'

import { createClient } from '@/utils/supabase/client'
import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { submitReport } from './actions' // We will update this next

// ... (Keep your existing Types and Search Logic) ...

export default function SubmitReportPage() {
  const supabase = createClient()
  const router = useRouter()

  const [step, setStep] = useState(1)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Form State
  const [selectedCadetId, setSelectedCadetId] = useState<string | null>(null)
  const [dateOfOffense, setDateOfOffense] = useState(new Date().toISOString().split('T')[0])
  const [offenseType, setOffenseType] = useState<string>('')
  
  // NEW: Split Notes into Two Fields
  const [greenSheetNotes, setGreenSheetNotes] = useState('') // Was 'notes'
  const [reportExplanation, setReportExplanation] = useState('') // New Field

  // ... (Keep existing cadet search & fetch logic) ...

  async function handleSubmit() {
    if (!selectedCadetId || !offenseType) return
    setLoading(true)
    setError(null)

    const result = await submitReport({
        cadetId: selectedCadetId,
        offenseTypeId: offenseType,
        dateOfOffense,
        notes: greenSheetNotes,          // Short Summary
        explanation: reportExplanation   // Full Narrative
    })

    if (result.success) {
        router.push('/')
    } else {
        setError(result.error || "Failed to submit")
        setLoading(false)
    }
  }

  // ... (Keep Step 1: Search Cadet UI) ...

  // STEP 2: OFFENSE DETAILS UI
  return (
    <div className="max-w-2xl mx-auto p-6 bg-white dark:bg-gray-800 rounded-lg shadow mt-10">
      <h1 className="text-2xl font-bold mb-6 text-gray-900 dark:text-white">Submit Report</h1>
      
      {/* ... (Keep Cadet Info Display & Offense Dropdown) ... */}

      {/* NEW: Report Explanation (The Full Story) */}
      <div className="mb-6">
        <label className="block text-sm font-bold text-gray-700 dark:text-gray-200 mb-1">
            Report Explanation (Full Narrative)
        </label>
        <p className="text-xs text-gray-500 dark:text-gray-400 mb-2">
            Detailed account of the event. Visible to Staff, Faculty, and the Subject Cadet.
        </p>
        <textarea
            value={reportExplanation}
            onChange={(e) => setReportExplanation(e.target.value)}
            className="w-full p-3 border rounded-md h-32 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
            placeholder="Describe the who, what, where, and when..."
        />
      </div>

      {/* UPDATED: Green Sheet Notes (The Short Summary) */}
      <div className="mb-6">
        <label className="block text-sm font-bold text-gray-700 dark:text-gray-200 mb-1">
            Green Sheet Summary (Public Notes)
        </label>
        <p className="text-xs text-amber-600 dark:text-amber-400 mb-2 font-medium">
            ⚠️ This text appears on the public Green Sheet. Keep it brief and professional.
        </p>
        <input
            type="text"
            value={greenSheetNotes}
            onChange={(e) => setGreenSheetNotes(e.target.value)}
            className="w-full p-3 border rounded-md dark:bg-gray-700 dark:border-gray-600 dark:text-white"
            placeholder="Ex: Late to formation; Unshaven; Disrespect"
            maxLength={100}
        />
      </div>

      {error && <p className="text-red-500 mb-4">{error}</p>}
      
      <button
        onClick={handleSubmit}
        disabled={loading}
        className="w-full bg-indigo-600 text-white py-3 rounded-md font-bold hover:bg-indigo-700 disabled:opacity-50"
      >
        {loading ? 'Submitting...' : 'Submit Report'}
      </button>
    </div>
  )
}